    H.ops.resolve(ownerDecision, H.halts.changed, H.halts.interrupted),
    H.ops.readMemory,
    H.ops.writeMemory,
    H.ops.readTelemetry,
    H.ops.readAccounts,
    H.ops.setShares,
    H.operation('production-health-probe', productionHealth),
