  .for(Incident)
  .does(async ctx => {
    const { title, detail } = ctx.unit.data;
    await ctx.run(pageOnCall, { title });
    await ctx.halt(acknowledged, `Acknowledge incident: ${title}`);
    while (true) {
      const ran = await ctx.run(runbook, { title, detail });
