  apiKey: H.env('LINEAR_API_KEY'),
  team: 'PROD',
  label: 'epic',
  read: issue => ({ title: issue.title, description: issue.description }),
  statuses: { queued: 'Todo', decomposed: 'In Progress', done: 'Done', abandoned: 'Canceled' },
