    for (let hour = 1; hour <= 14 * 24; hour += 1) {
      const sample = await ctx.run(measureArms, { experiment: ctx.unit.data.name });
      if (sample.ok) samples.push(sample.value);
      await ctx.wait('collecting', { at: new Date(start + hour * hourMs) });
