  .handler(answerConversation)
  .retries(2, { backoff: { first: { minutes: 2 }, factor: 2 }, exhausted: 'unanswered' })
  .suppliers(helpdeskWebhook, helpdeskPoll)
  .store(helpdeskStore)
  .wip(5)
  .maxUsdPerUnit(0.4)
  .facet(category, data => data.category);

